abstract class ReportExporter {
  // Factory method: subclasses decide the concrete product.
  abstract ReportWriter createWriter();

  public void export(Report r) {
    ReportWriter w = createWriter(); // caller never names PdfWriter/CsvWriter
    w.write(r);
  }
}
class PdfExporter extends ReportExporter {
  @Override ReportWriter createWriter() { return new PdfWriter(); }
}

final class HttpClientConfig {
  private final String host; private final int timeoutMs; private final boolean retry;
  private HttpClientConfig(Builder b) {
    this.host = b.host; this.timeoutMs = b.timeoutMs; this.retry = b.retry;
  }
  static final class Builder {
    private String host; private int timeoutMs = 1000; private boolean retry;
    Builder host(String h) { this.host = h; return this; }
    Builder timeoutMs(int t) { this.timeoutMs = t; return this; }
    Builder retry(boolean r) { this.retry = r; return this; }
    HttpClientConfig build() {
      if (host == null || host.isBlank()) throw new IllegalStateException("host required");
      if (timeoutMs <= 0) throw new IllegalStateException("timeout must be positive");
      return new HttpClientConfig(this); // single validation gate
    }
  }
}

enum ConnectionRegistry { INSTANCE; // enum idiom: serialization + reflection safe
  private final Map<String, PooledConnection> pool = new ConcurrentHashMap<>();
  PooledConnection get(String key, Supplier<PooledConnection> factory) {
    return pool.computeIfAbsent(key, k -> factory.get());
  }
}
